#!/bin/bash
# Start/stop the FRC vision scorer server on the pod.
#
#   bash /workspace/frc/deploy/runpod/serve.sh {start|stop|restart|status}
#
# Pod equivalent of web/start_all.sh + web/start.sh: same env defaults
# (via profile.env, generated by profiles.py from BASE_ENV, which mirrors
# start_all.sh), log + pid on the volume, detached with setsid so it outlives
# the ssh session. The app binds 0.0.0.0:8004 but the pod only exposes 22/tcp,
# so it is reachable only through `runpod_cli.py tunnel` (it has no auth).
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=pod_env.sh
source "$HERE/pod_env.sh"
LOG="$FRC_LOGS/server.log"
PIDF="$FRC_LOGS/server.pid"
PORT=8004
mkdir -p "$FRC_LOGS"

is_running() {
  [ -f "$PIDF" ] && kill -0 "$(cat "$PIDF")" 2>/dev/null
}

do_stop() {
  if is_running; then
    pid="$(cat "$PIDF")"
    echo "stopping server pid $pid"
    kill "$pid" 2>/dev/null || true
    for _ in $(seq 1 30); do kill -0 "$pid" 2>/dev/null || break; sleep 1; done
    kill -9 "$pid" 2>/dev/null || true
  fi
  # strays (e.g. started by hand)
  pkill -f "$FRC_APP/.venv/bin/python web/app.py" 2>/dev/null || true
  rm -f "$PIDF"
}

do_start() {
  if is_running; then echo "already running (pid $(cat "$PIDF"))"; return 0; fi
  cd "$FRC_APP" || exit 1
  set -a
  # shellcheck disable=SC1091
  [ -f "$FRC_APP/profile.env" ] && . "$FRC_APP/profile.env"
  set +a
  # Secrets are NOT exported here: web/app.py load_dotenv()s $FRC_APP/.env.
  echo "=== start $(date -Is) rung=${FRC_PROFILE_RUNG:-?} tier=${FRC_GPU_TIER:-?}" >> "$LOG"
  setsid nohup "$FRC_APP/.venv/bin/python" web/app.py >> "$LOG" 2>&1 < /dev/null &
  echo $! > "$PIDF"
  echo "started pid $(cat "$PIDF"); log $LOG"
  for i in $(seq 1 240); do
    code="$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:$PORT/" || true)"
    if [ "$code" = 200 ]; then echo "server up on :$PORT after ${i}s"; return 0; fi
    if ! is_running; then echo "server exited during startup; last log lines:"; tail -n 40 "$LOG"; return 1; fi
    sleep 1
  done
  echo "server not answering on :$PORT after 240s; last log lines:"; tail -n 40 "$LOG"; return 1
}

case "${1:-status}" in
  start) do_start ;;
  stop) do_stop ;;
  restart) do_stop; do_start ;;
  status)
    if is_running; then
      echo "running pid $(cat "$PIDF")"
      curl -s "http://127.0.0.1:$PORT/api/job/active"; echo
    else
      echo "not running"; exit 3
    fi ;;
  *) echo "usage: $0 {start|stop|restart|status}" >&2; exit 2 ;;
esac
